<?php
namespace App\Http\Controllers; use App\Models\{Sale,Purchase,Expense,Item,SaleItem}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; class ReportController extends Controller {public function index(Request $r){$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$sales=Sale::whereBetween('sale_date',[$from,$to]);$purchases=Purchase::whereBetween('purchase_date',[$from,$to]);$expenses=Expense::whereBetween('expense_date',[$from,$to]);$saleRows=(clone $sales)->with('items.item')->orderBy('sale_date')->get();$purchaseRows=(clone $purchases)->with('items.item')->orderBy('purchase_date')->get();return view('reports.index',compact('from','to','saleRows','purchaseRows')+['saleTotal'=>(clone $sales)->sum('total'),'received'=>(clone $sales)->sum('paid_amount'),'salesDue'=>DB::table('sales')->whereBetween('sale_date',[$from,$to])->selectRaw('COALESCE(SUM(total-paid_amount),0) as x')->value('x'),'purchaseTotal'=>(clone $purchases)->sum('total'),'purchasePaid'=>(clone $purchases)->sum('paid_amount'),'expenseTotal'=>(clone $expenses)->sum('amount'),'profitTotal'=>SaleItem::whereHas('sale',function($q)use($from,$to){$q->whereBetween('sale_date',[$from,$to]);})->selectRaw('COALESCE(SUM((unit_price-unit_cost)*quantity),0) as profit')->value('profit'),'items'=>Item::with('category')->orderBy('name')->get()]);} public function stockCsv(){ $items=Item::with('category')->orderBy('name')->get();$name='stock-report-'.now()->format('Y-m-d').'.csv';return response()->streamDownload(function()use($items){$o=fopen('php://output','w');fputcsv($o,['SKU','Item','Category','Buying Price','Selling Price','Quantity','Stock Cost Value']);foreach($items as $i)fputcsv($o,[$i->sku,$i->name,$i->category?->name,$i->buying_price,$i->selling_price,$i->quantity,$i->quantity*$i->buying_price]);fclose($o);},$name);} public function salesCsv(Request $r){$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$sales=Sale::whereBetween('sale_date',[$from,$to])->get();$name='sales-report-'.$from.'-'.$to.'.csv';return response()->streamDownload(function()use($sales){$o=fopen('php://output','w');fputcsv($o,['Invoice','Date','Customer','Type','Total','Received','Credit Due']);foreach($sales as $s)fputcsv($o,[$s->invoice_no,$s->sale_date->format('Y-m-d'),$s->customer_name,$s->sale_type,$s->total,$s->paid_amount,$s->total-$s->paid_amount]);fclose($o);},$name);}}
